contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller (msg.sender for c calls) is this contract
    // Inputs: callerIsAdmin controls whether we set isAdmin[this] via direct storage is not allowed,
    // so we must use the public surface: C has mapping isAdmin public, but no setter; however
    // the only way to make an address an admin is not available through public functions.
    // Instead we test the following invariant observable through public surface:
    // Calling newEmergencyOracle by this contract either reverts (if not admin) or succeeds
    // (if admin) — we check revert boolean and that when it succeeds, address(c).balance is unchanged
    // and the created oracle address (emitted) is non-zero by observing that contract creation returns an address
    // but solidity cannot read event logs. Therefore we assert the simpler general rule:
    // A call to newEmergencyOracle either reverts, or if it does not revert then c.isAdmin(address(this)) must be true afterwards.
    // This encodes that only admins can successfully call newEmergencyOracle.

    function run(bool tryCall) public payable {
        require(true);

        bool reverted;
        if (tryCall) {
            // perform the state-changing call as top-level statement and catch revert
            try c.newEmergencyOracle("desc") {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // If caller chooses not to call, set reverted = true to make assertion meaningful
            reverted = true;
        }

        // Observe whether this contract is an admin according to public getter
        bool amAdmin = c.isAdmin(address(this));

        // General rule: if the call did not revert then this contract must be admin according to the public mapping
        assert(reverted || amAdmin);
    }

    receive() external payable {}
}

