    function run(string calldata description) public payable {
        require(bytes(description).length >= 0, true);

        // Attempt the possibly-reverting call and record whether it reverted.
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe the admin status after the call.
        bool isAdminAfter = c.isAdmin(address(this));

        // The general rule: if the call succeeded then the onlyAdmin check must have held at entry.
        // Since C does not expose any function that mutates isAdmin in newEmergencyOracle, the mapping cannot be toggled by the call itself
        // (and onlyAdmin prevents entry without being admin). Thus success implies isAdminAfter == true.
        // Conversely, if isAdminAfter == false then the call must have reverted.
        assert(reverted == (!isAdminAfter));
    }

    receive() external payable {}
}

